//! Cannons and cannonballs (docs/CANNONS.md): the data's table (shared/cannons/cannons.json,
//! generated by shared/cannons/gen.mjs) and lookups. A cannon is a block whose Use fires it (block
//! data `use: fire`); what a shot does is the server's (C2: the ball).

/// What a ball does to what it runs into (owner, 2026-11-18; shared/cannons `impact`).
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Impact {
    /// At this speed (m/s) or more each breakable block it runs into is destroyed; slower, knocked
    /// loose as a physics block.
    pub destroy_speed_ms: f64,
    /// The energy it loses (J) for each kg of a block it destroys.
    pub energy_per_kg_j: f64,
    /// At a hit the breakable cells within it (m, of the ball's centre) come loose, and every loose
    /// piece within it is pushed along the ball's velocity.
    pub drag_radius_m: f64,
    /// That push (N) for each m/s of the ball's speed, every tick.
    pub drag_force_per_speed_n: f64,
    /// The most cells a tick's hits loosen round it.
    pub max_loose_cells: u32,
    /// Slower (m/s) it destroys, loosens and drags nothing.
    pub min_speed_ms: f64,
}

/// A ship's helm (C5): a block a player takes the helm at; while the ship is afloat its forward and
/// back push it with its mass × `thrust_accel_ms2` along the helm's facing from its centre of mass, and left and right
/// turn it by `turn_rad_s2_per_ms` (rad/s²) for each m/s it moves along its heading.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct HelmDef {
    pub block: &'static str,
    /// The push's acceleration (m/s²): its force is the ship's mass times it (owner, 2026-11-18: "The
    /// movement force should be scaled based on the mass of the boat").
    pub thrust_accel_ms2: f64,
    /// The rudder's turn (rad/s²) for each m/s the ship moves along its heading, whatever its size.
    pub turn_rad_s2_per_ms: f64,
    pub camera: HelmCamera,
    pub wheel: HelmWheel,
}

/// A helm's look (owner, 2026-11-18: "A spoked wheel model"; its block's look `wheel`): a post up
/// to the hub `hub_m` over the cell's floor, a rim of `radius_m` with `spokes` spokes running
/// `handle_m` out past it, across the helm's facing.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct HelmWheel {
    pub radius_m: f64,
    pub hub_m: f64,
    pub spokes: u32,
    pub handle_m: f64,
}

/// The view at a helm (owner, 2026-11-18: "The camera should smoothly transition to 3rd person when
/// you grab the helm"): eased out over `ease_s` to `back_m` behind the eye along the look and `up_m`
/// up, and back in on leaving it.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct HelmCamera {
    pub back_m: f64,
    pub up_m: f64,
    pub ease_s: f64,
}

/// The helm whose block is `block`, if any.
pub fn helm(block: &str) -> Option<&'static HelmDef> {
    HELMS.iter().find(|h| h.block == block)
}

/// A cannonball.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct BallDef {
    pub name: &'static str,
    pub radius_m: f64,
    /// Its rolling resistance: its speed's damping (1/s) while it touches the ground.
    pub roll_damping: f64,
    pub density_kg_m3: f64,
    pub impact: Impact,
}

impl BallDef {
    /// Its mass (kg): a sphere of its radius at its density.
    pub fn mass_kg(&self) -> f64 {
        4.0 / 3.0 * std::f64::consts::PI * self.radius_m.powi(3) * self.density_kg_m3
    }
}

/// A cannon: its block, the ball it fires and how.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct CannonDef {
    pub block: &'static str,
    pub ball: &'static str,
    pub muzzle_speed_ms: f64,
    /// The barrel's tilt up from level along its facing (degrees).
    pub elevation_deg: f64,
    pub muzzle_up_m: f64,
    pub muzzle_forward_m: f64,
    /// The share of the ball's momentum that pushes a body the cannon stands on back (0–1).
    pub recoil_share: f64,
    pub reload_s: f64,
    /// Its shot's looks at the muzzle (owner, 2026-11-18: "Flash + smoke puff"): the explosives'
    /// schema; its boom is its block's sound set's `explode`.
    pub fire: crate::explosives::BlastEffects,
}

mod table {
    include!("cannons.gen.rs");
}
pub use table::{BALLS, CANNONS, HELMS};

/// The cannon whose block is `block` (a name), if any.
pub fn cannon(block: &str) -> Option<&'static CannonDef> {
    CANNONS.iter().find(|c| c.block == block)
}

/// The ball named `name`, if any.
pub fn ball(name: &str) -> Option<&'static BallDef> {
    BALLS.iter().find(|b| b.name == name)
}

/// The rear bottom cell (where it was placed) of the multi-cell block whose state `m` is at `cell`
/// (its column's first cell: back along its facing and down its rows); `cell` for a block without a
/// column.
pub fn anchor_of(cell: [i32; 3], m: dwell_blocks::StateId) -> [i32; 3] {
    anchor_in(cell, m, crate::FaceFrame::at_row(cell[1]))
}

/// [`anchor_of`] in a grid whose up is face `f`'s: a moving body's own grid (docs/CANNONS.md C4),
/// whose rows are no world rows to read a face from.
pub fn anchor_in(cell: [i32; 3], m: dwell_blocks::StateId, f: crate::FaceFrame) -> [i32; 3] {
    let Some(s) = dwell_blocks::try_info(m) else {
        return cell;
    };
    let Some(c) = s.column else {
        return cell;
    };
    let (a, r) = c.place_of(c.index);
    let up = f.cell([0, 1, 0])[1] - f.cell([0, 0, 0])[1];
    let ahead = crate::parts::forward(s.facing);
    if ahead[1] != 0 {
        // Up or down: the rear bottom cell is the column's first row along the facing.
        return [
            cell[0],
            cell[1] - up * ahead[1] * crate::parts::column_row(c, c.index),
            cell[2],
        ];
    }
    [
        cell[0] - ahead[0] * a,
        cell[1] - up * r,
        cell[2] - ahead[2] * a,
    ]
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_cannon_fires_a_heavy_steel_ball() {
        // face-a-only: data, no geometry.
        let c = cannon("dwell:cannon").expect("the land cannon is data");
        let b = ball(c.ball).expect("its ball");
        // Owner, 2026-11-17: "Should have high mass as it's a heavy steel ball"; 2026-11-18:
        // "double the size", "8× mass, real steel" (r 0.24 m: ~455 kg); one ball replaces the two.
        assert!((b.radius_m - 0.24).abs() < 1e-9);
        assert!((b.mass_kg() - 454.6).abs() < 1.0, "{} kg", b.mass_kg());
        assert_eq!(BALLS.len(), 1, "one ball design");
        assert!(b.impact.destroy_speed_ms == 20.0 && b.impact.drag_radius_m == 1.0);
        // No fire-rate cap (owner, 2026-11-18: "set that to off or none").
        assert_eq!(c.reload_s, 0.0);
    }
}
